#include <numbers>

namespace geometry
{
    namespace v1
    {
        double area(double radius)
        {
            return 3.14 * radius * radius;
        }
    }

    inline namespace v2
    {
        double area(double radius)
        {
            return std::numbers::pi * radius * radius;
        }
    }
}
